def fib_space_optimized(n):
    if n < 0:
        raise ValueError('n must be non-negative')
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

print(fib_space_optimized(10))

def remove_duplicates(arr):
    if not arr:
        return 0
    write = 1
    for read in range(1, len(arr)):
        if arr[read] != arr[read - 1]:
            arr[write] = arr[read]
            write += 1
    return write

arr = [1, 1, 2, 2, 3, 3, 3]
print(remove_duplicates(arr))

